s=Path('/mnt/data/Ilha_Viva_Laboratorio_15.html').read_text();d,_=json.JSONDecoder().raw_decode(s[s.index('const DATA=')+11:]);f=d['atlas']['topdown']['idle']['down'][0];im=d['images'][f['id']];print(f, type(im),str(im)[:60]);
