html='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ilha Viva | Régua de escala</title><style>*{box-sizing:border-box}body{margin:0;background:#17251f;color:#e8eee7;font:15px system-ui}main{max-width:900px;margin:auto;padding:14px}canvas{display:block;width:100%;height:auto;background:#273b30;border:1px solid #54735e;border-radius:8px;image-rendering:pixelated}label{display:block;margin:10px 0}select{font:inherit;padding:7px;background:#354a3f;color:white}p{line-height:1.4;color:#cad6c9}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;border-bottom:1px solid #40554a;padding:8px}</style><main><h1>Ilha Viva | Escala e geometria 01</h1><p>Régua diagnóstica, com o sprite original. Volumes geométricos, não artes finais. Câmera proposta de 45°; personagem em pé, projeção ortográfica.</p><label>Exibir <select id="view"><option value="all">Conjunto completo</option><option value="animal">Fauna e jogador</option><option value="building">Construção e jogador</option></select></label><canvas id="cv" width="720" height="520"></canvas><p id="status"></p><table><thead><tr><th>Elemento</th><th>Dimensão de referência</th></tr></thead><tbody><tr><td>Jogador</td><td>1,75 m (convenção artística)</td></tr><tr><td>Porta</td><td>0,90 × 2,10 m</td></tr><tr><td>Casa de teste</td><td>4 × 3 × 3,8 m</td></tr><tr><td>Lêmure</td><td>0,45 m altura ilustrativa</td></tr><tr><td>Fossa</td><td>0,35 m até o ombro</td></tr><tr><td>Tartaruga</td><td>0,40 m comprimento de casco</td></tr><tr><td>Árvore jovem</td><td>5 m altura ilustrativa</td></tr></tbody></table><p>A escala de câmera é experimental: tamanho das espécies, poses, perspectiva e silhuetas finais precisam de validação. Insetos pequenos poderão receber realce de seleção, sem aumentar seu alcance físico.</p></main><script>const canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d'),hero=new Image(); const f=FRAME; hero.src=IMAGE;const q=Math.SQRT1_2,S=f.ay/(1.75*q);const origin=[360,375];function P(x,y,z=0){return [origin[0]+x*S,origin[1]+y*S*q-z*S*q]}function poly(pts,fill,stroke='#afc2aa'){ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(...P(...p)):ctx.moveTo(...P(...p)));ctx.closePath();ctx.fillStyle=fill;ctx.fill();ctx.strokeStyle=stroke;ctx.stroke()}function line(a,b,c='#7e9980'){ctx.beginPath();ctx.moveTo(...P(...a));ctx.lineTo(...P(...b));ctx.strokeStyle=c;ctx.stroke()}function label(t,x,y,z=0){let p=P(x,y,z);ctx.fillStyle='#f1e8ca';ctx.font='13px system-ui';ctx.textAlign='center';ctx.fillText(t,p[0],p[1]-7)}function box(x,y,w,d,h,c){poly([[x,y,0],[x+w,y,0],[x+w,y+d,0],[x,y+d,0]],'#314638');poly([[x,y+d,0],[x+w,y+d,0],[x+w,y+d,h],[x,y+d,h]],c);poly([[x+w,y,0],[x+w,y+d,0],[x+w,y+d,h],[x+w,y,h]],'#675d49');poly([[x,y,h],[x+w,y,h],[x+w,y+d,h],[x,y+d,h]],'#9d8f69')}
function draw(){ctx.clearRect(0,0,720,520);let mode=document.querySelector('#view').value;for(let x=-5;x<=5;x++)line([x,-6],[x,3]);for(let y=-6;y<=3;y++)line([-5,y],[5,y]);if(mode!=='animal'){box(-4.6,-4.6,4,3,2.8,'#95714e');poly([[-4.6,-1.6,2.8],[-.6,-1.6,2.8],[-2.6,-1.6,3.8]],'#806045');poly([[-.6,-4.6,2.8],[-.6,-1.6,2.8],[-2.6,-1.6,3.8],[-2.6,-4.6,3.8]],'#a78b5e');poly([[-3,-1.6,0],[-2.1,-1.6,0],[-2.1,-1.6,2.1],[-3,-1.6,2.1]],'#42372b');label('Casa • porta 2,10 m',-2.6,-4.6,3.8);if(mode==='all'){box(3,-3,.45,.45,4.2,'#735640');let [a,b]=P(3.225,-2.775,4.4);ctx.fillStyle='#628650';ctx.beginPath();ctx.ellipse(a,b,52,34,0,0,Math.PI*2);ctx.fill();label('Árvore jovem',3.2,-2.7,5.3)}}let hp=P(0,0);ctx.fillStyle='#17251f';ctx.beginPath();ctx.ellipse(hp[0],hp[1],20,8,0,0,Math.PI*2);ctx.fill();if(hero.complete&&hero.naturalWidth)ctx.drawImage(hero,hp[0]-f.ax,hp[1]-f.ay,f.w,f.h);label('Jogador • 1,75 m',0,0,1.9);if(mode!=='building'){box(-3,.8,.55,.28,.45,'#b5aa98');label('Lêmure',-2.7,.8,.65);box(-1.6,1.5,.75,.3,.35,'#b27e55');label('Fossa',-1.2,1.5,.55);box(1.4,1.2,.4,.28,.23,'#ae9959');label('Tartaruga',1.6,1.2,.45);box(3.3,1.4,.3,.12,.14,'#82a45b');label('Camaleão',3.4,1.4,.38)}line([-4.5,2.8],[-3.5,2.8],'#fff');label('1 m',-4,2.8,.1);document.querySelector('#status').textContent=`Referência: ${S.toFixed(1)} px/m horizontal; ${(S*q).toFixed(1)} px/m vertical e profundidade. Pé do jogador é a âncora; malha de solo de 1 m.`}hero.onload=draw;document.querySelector('#view').onchange=draw;draw();</script></html>'''
html=html.replace('FRAME',json.dumps(f)).replace('IMAGE',json.dumps(im));(p/'Ilha_Viva_Escala_01.html').write_text(html)
